    personDue(live((claims.data ?? []).filter((c) => c.personId === p.id), [p]), rates.data, p.grades, today, floor, lateOf(settings, today, [p]), capOf(p), shared(p));
}

/** The cap each person's due-total on the sheet (the current sheet's unless another is named) is held to: the
 *  sheet's cap less their cut total (see `capLess`). */
export function useCapOf(of?: string): (person: Person) => string | null | undefined {
  const [current] = useCurrentSheet();
  const sheet = of ?? current;
  const cap = useSettings(sheet).data?.cap;
  const pools = usePools(sheet).data ?? [];
  return (p: Person) => capLess(cap, cutTotal(pools, p.id));
}

/** What claims shared with or by each person on the sheet (the current sheet's unless another is named) move in
 *  their figures (see `sharedParts`); undefined for a person no shared claim touches. */
export function useShared(of?: string): (person: Person) => Shared | undefined {
  const [current] = useCurrentSheet();
  const sheet = of ?? current;
  const people = usePeople(sheet).data ?? [];
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  const parts = sharedParts(live(claims.data ?? [], people), people, rates.data, floorOf(settings), lateOf(settings, today, people), today);
  return (p: Person) => parts.get(p.id);
}

function DueTotal() {
  const fig = useFigure();
  return (
    <p>
      Due total <strong data-testid="rollup-due-total">{fig(useSheetDueTotal())}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 15, Component: DueHead }),
  PersonColumns.fill({ order: 15, Component: PersonDue }),
  PersonColumnHeads.fill({ order: 15.5, Component: ExcessHead }),
  PersonColumns.fill({ order: 15.5, Component: PersonExcess }),
  HomeMain.fill({ order: 35, Component: DueTotal }),
];
/** The sum of each figure (n/a counted as none) times its share ÷ 100, rounded half to even to two decimals. */
export function sharedTotal(parts: { figure: string; share: string }[]): string {
  // figure (hundredths) × share (hundredths) is in units of 1/10000 cent-percent: ÷ 10000 gives cents.
  const product = parts
    .filter((p) => p.figure !== NA)
    .reduce((sum, p) => sum + hundredths(p.figure) * hundredths(p.share), 0n);
  const abs = product < 0n ? -product : product;
  const rest = abs % 10000n;
  let cents = abs / 10000n;
  if (rest > 5000n || (rest === 5000n && cents % 2n === 1n)) cents += 1n;
  return format(product < 0n ? -cents : cents);
}

/** A sheet total of people's figures: their sum, skipping n/a, leaving out the single highest and the
 *  single lowest when three or more people have a figure. */
export function trimmedTotal(dues: string[]): string {
  const figures = dues.filter((d) => d !== NA).map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const kept = figures.length >= 3 ? figures.slice(1, -1) : figures;
  return format(kept.reduce((sum, d) => sum + d, 0n));
}

/** What a claim's late charge follows: the sheet's late percent (two decimals) in force on a date and the
 *  30-day boundaries (yyyy-MM-dd) the claim is overdue past; and whether the claim's live figures round half up (else half to even);
 *  and the date (yyyy-MM-dd) its overdue is counted from: its due-by plus any grace days of its person's grade. */
export type Late = { pct: ((date: string) => string) | undefined; boundaries: (claim: Claim) => string[]; halfUp?: (claim: Claim) => boolean;
  graceBy?: (claim: Claim) => string };

/** The sheet's floor (two decimals) in force on a date; undefined for none known. */
export type Floor = ((date: string) => string) | undefined;

/** The late charge on a figure, compounding: for every full 30 days overdue, the late percent in force on that
 *  boundary of the figure plus the charges of the boundaries before it, rounded like due, added up (a boundary at
 *  0.00 adds nothing). None on a correction, nor on a claim whose charge was waived. */
function lateCharge(claim: Claim, figure: string, late: Late | undefined): string | undefined {
  const boundaries = late?.pct === undefined || isCorrection(claim) || claim.waived ? [] : late.boundaries(claim);
  if (boundaries.length === 0 || figure === NA) return undefined;
  const halfUp = late?.halfUp?.(claim) ?? false;
  return format(boundaries.reduce(
    (sum, b) => sum + hundredths(due(format(hundredths(figure) + sum), late!.pct!(b), halfUp)), 0n));
}

/** Whether the claim keeps a figure whatever the rates: fixed when settled, or bound by a statement to a
 *  figure (bound to n/a keeps no figure). */
const fixed = (claim: Claim) => claim.due !== null || (isBound(claim) && claim.statedDue !== null);

/** A claim's due: the due fixed when it was settled (its late charge frozen in), else the due as shown its
 *  person's last statement bound it to (its late charge and floor in it), else its figure — its amount at the rate in force
 *  on the claim's date of its person's grade in force on that date — raised to at least the sheet's floor in force
 *  on the claim's date, applied first, plus its late charge when overdue (worked out on that floored figure).
 *  A correction's live due has no floor and it has no late charge.
 *  While bound by a statement, its late charge no longer follows the sheet's today. */
export function claimDue(
  claim: Claim,
  rates: Rate[] | undefined,
  grades: Grades,
  floor: Floor,
  late?: Late,
): string {
  if (claim.due !== null) return claim.due;
  if (isBound(claim)) return claim.statedDue ?? NA;
  const pct = rateOf(ratesFor(rates, claim), gradeOn(grades, claim.date), claim.date);
  const halfUp = late?.halfUp?.(claim) ?? false;
  const figure = due(claim.amount, pct, halfUp);
  const floored = isCorrection(claim) ? figure : liveDue(figure, floor?.(claim.date));
  const charge = lateCharge(claim, floored, late);
  return charge === undefined ? floored : format(hundredths(floored) + hundredths(charge));
}

/** The cap a person's due-total is held to: the sheet's cap less their cut total, not below 0.00 (null or
 *  undefined for no cap). */
export function capLess(cap: string | null | undefined, cut: string): string | null | undefined {
  if (cap == null) return cap;
  const less = hundredths(cap) - hundredths(cut);
  return format(less < 0n ? 0n : less);
}

/** A person's due-total: the sum of the figures of their claims that count, moved by the claims shared with or by
 *  them (see `Shared`), at most `cap`, the cap they are held to (see `capLess`)
 *  (two decimals; null or undefined for none). n/a when their grade
 *  in force on the sheet's today has no rate then, unless a claim that counts keeps a fixed (settled or
 *  stated) figure, or a figure at another grade (the one in force on its date), or at a rate that ended before today;
 *  n/a is not capped. */
export function personDue(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
  cap?: string | null,
  shared?: Shared,
): string {
  const total = uncappedDue(claims, rates, grades, today, floor, late, shared);
  return total === NA || cap == null || hundredths(total) <= hundredths(cap) ? total : format(hundredths(cap));
}

/** A person's excess: how far the sum of their figures is above `cap`, the cap they are held to (see `capLess`); 0.00 when it is not, or
 *  there is no cap, or their due-total is n/a. */
export function personExcess(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
  cap?: string | null,
  shared?: Shared,
): string {
  const total = uncappedDue(claims, rates, grades, today, floor, late, shared);
  return total === NA || cap == null || hundredths(total) <= hundredths(cap)
    ? format(0n)
    : format(hundredths(total) - hundredths(cap));
}

/** A person's due-total before the cap (see `personDue`). */
function uncappedDue(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
  shared?: Shared,
): string {
  const mine = claims.filter(counts);
  const now = gradeOn(grades, today);
  const elsewhere = (c: Claim) => {
    const grade = gradeOn(grades, c.date);
    const theirs = ratesFor(rates, c);
    return rateOf(theirs, grade, c.date) !== undefined
      && (grade !== now || (today !== undefined && endsBefore(theirs, grade, c.date, today)));
  };
  if (rateOf(rates, now, today) === undefined && !shared?.holds && !mine.some((c) => fixed(c) || elsewhere(c))) {
    return NA;
  }
  return dueTotal([...mine.map((c) => claimDue(c, rates, grades, floor, late)), shared?.settled ?? NA, shared?.open ?? NA]);
}

/** What claims shared with or by a person move in their figures: the parts of the claims shared with them less the
 *  parts of theirs held by others, of SETTLED claims (`scored` leaving out corrections) and of OPEN or PENDING ones,
 *  two decimals each; and whether they hold a part that keeps their due-total from n/a: a frozen one, or one at a
 *  grade other than theirs today, or at a rate that ended before today. */
export type Shared = { settled: string; open: string; scored: string; holds: boolean };

/** A holder's part of a claim's amount: amount × share ÷ 100 × pct ÷ 100, rounded half to even (half up when
 *  `halfUp`) to two decimals; 0.00 when there is no rate. */
export function sharePart(amount: string, share: string, pct: string | undefined, halfUp = false): string {
  if (pct === undefined) return format(0n);
  // amount, share and pct (each in hundredths) multiplied, ÷ 100000000 gives cents (the two ÷ 100 included).
  const product = hundredths(amount) * hundredths(share) * hundredths(pct);
  const abs = product < 0n ? -product : product;
  const rest = abs % 100000000n;
  let cents = abs / 100000000n;
  if (rest > 50000000n || (rest === 50000000n && (halfUp || cents % 2n === 1n))) cents += 1n;
  return format(product < 0n ? -cents : cents);
}

/** Each person's `Shared`, by id: a holder's part of a shared claim that counts (`claims` already filtered to those
 *  live) whose due (as its person's row shows it) is not n/a is its amount times their share divided by 100, times
 *  the rate of the holder's own grade in force on the claim's date divided by 100, rounded like the claim (0.00 when
 *  their grade has no rate); a SETTLED claim's parts are frozen: its due times each share divided by 100, rounded
 *  half to even. */
export function sharedParts(
  claims: Claim[],
  people: { id: number; grades: Grades }[],
  rates: Rate[] | undefined,
  floor: Floor,
  late: Late | undefined,
  today?: string,
): Map<number, Shared> {
  const moves = new Map<number, { settled: bigint; open: bigint; scored: bigint; holds: boolean }>();
  const of = (id: number) => {
    let m = moves.get(id);
    if (m === undefined) moves.set(id, (m = { settled: 0n, open: 0n, scored: 0n, holds: false }));
    return m;
  };
  const byId = new Map(people.map((p) => [p.id, p]));
  for (const c of claims) {
    const owner = byId.get(c.personId);
    if (owner === undefined || !c.shares?.length || !counts(c)) continue;
    const figure = claimDue(c, rates, owner.grades, floor, late);
    if (figure === NA) continue;
    const frozen = c.status === 'SETTLED';
    for (const h of c.shares) {
      const grades = byId.get(h.personId)?.grades;
      const grade = grades === undefined ? undefined : gradeOn(grades, c.date);
      const theirs = ratesFor(rates, c);
      const pct = grade === undefined ? undefined : rateOf(theirs, grade, c.date);
      const part = hundredths(frozen
        ? sharedTotal([{ figure, share: h.share }])
        : sharePart(c.amount, h.share, pct, late?.halfUp?.(c) ?? false));
      const key = frozen ? 'settled' : 'open';
      const holder = of(h.personId);
      const own = of(c.personId);
      holder[key] += part;
      own[key] -= part;
      // A frozen part, or one at a grade other than the holder's today or at a rate that ended before today, does
      // not hang on today's grade's rate.
      if (frozen || (pct !== undefined && grade !== undefined
        && (grade !== gradeOn(grades!, today) || (today !== undefined && endsBefore(theirs, grade, c.date, today))))) {
        holder.holds = true;
      }
      if (key === 'settled' && !correctsAnother(c)) {
        holder.scored += part;
        own.scored -= part;
      }
    }
  }
  return new Map(Array.from(moves, ([id, m]) => [id, { settled: format(m.settled), open: format(m.open), scored: format(m.scored), holds: m.holds }]));
}

/** A person's settled-total and open-total: the sum of the dues (skipping n/a) of their claims that count
 *  that are SETTLED (at their frozen figures), and that are OPEN or PENDING. Together they make their
 *  due-total before the cap (0.00 each when it is n/a). */
export function personSplit(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
  shared?: Shared,
): { settled: string; open: string; scored: string } {
  if (uncappedDue(claims, rates, grades, today, floor, late, shared) === NA)
    return { settled: format(0n), open: format(0n), scored: format(0n) };
  const mine = claims.filter(counts);
  const total = (keep: (c: Claim) => boolean, part: string | undefined) =>
    dueTotal([...mine.filter(keep).map((c) => claimDue(c, rates, grades, floor, late)), part ?? NA]);
  return {
    settled: total((c) => c.status === 'SETTLED', shared?.settled),
    open: total((c) => c.status !== 'SETTLED', shared?.open),
    // The settled figures the score counts: corrections left out.
    scored: total((c) => c.status === 'SETTLED' && !correctsAnother(c), shared?.scored),
  };
}

/** A person's due on a tag: the sum of the dues (skipping n/a) of their claims that count that carry it, or
 *  all of them when the person (whose tags are `personTags`) carries it, each once; 0.00 when their due-total is n/a. */
export function personTagged(
  claims: Claim[],
  tag: string,
  personTags: string[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
): string {
  return personDueWhere(claims, (c) => personTags.includes(tag) || c.tags.includes(tag), rates, grades, today, floor, late);
}

/** A person's due in a calendar month (yyyy-mm): the sum of the dues (skipping n/a) of their claims that
 *  count dated in it; 0.00 when their due-total is n/a. */
export function personMonthDue(
  claims: Claim[],
  month: string,
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
): string {
  return personDueWhere(claims, (c) => c.date.slice(0, 7) === month, rates, grades, today, floor, late);
}

/** The sum of the dues (skipping n/a) of a person's claims that count that `keep` picks; 0.00 when their
 *  due-total is n/a. */
