    private final PeriodStore periods;

    public SheetCloneStore(JdbcTemplate jdbc, SheetStore sheets, PersonStore people, ClaimStore claims,
            ClaimLogStore log, SettingStore settings, PeriodStore periods) {
        this.jdbc = jdbc;
        this.sheets = sheets;
        this.people = people;
        this.claims = claims;
        this.log = log;
        this.settings = settings;
        this.periods = periods;
    }

    public void cloneTo(String from, String to) throws InvalidSheetException {
        if (sheets.exists(to)) {
            throw new InvalidSheetException("The sheet " + to + " is already in use");
        }
        sheets.markLoaded(to);
        sheets.setToday(to, sheets.today(from));
        jdbc.update("INSERT INTO sheet_source (sheet_id, source_id) VALUES (?, ?)", to, from);

        jdbc.update("INSERT INTO sheet_setting (sheet_id, setting_key, setting_value) "
                + "SELECT ?, setting_key, setting_value FROM sheet_setting WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value) "
                + "SELECT ?, setting_key, from_date, setting_value FROM sheet_setting_from WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO sheet_role (sheet_id, user_name, role) "
                + "SELECT ?, user_name, role FROM sheet_role WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date, to_date, version, forward_seq) "
                + "SELECT ?, grade, pct, from_date, to_date, version, forward_seq FROM rate WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO rate_version (sheet_id, grade, from_date, version, pct, to_date, forward_seq) "
                + "SELECT ?, grade, from_date, version, pct, to_date, forward_seq FROM rate_version WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO holiday (sheet_id, holiday_date) "
                + "SELECT ?, holiday_date FROM holiday WHERE sheet_id = ? ORDER BY id", to, from);
        jdbc.update("INSERT INTO grade_added (sheet_id, grade) "
                + "SELECT ?, grade FROM grade_added WHERE sheet_id = ? ORDER BY id", to, from);
        jdbc.update("INSERT INTO grade_retired (sheet_id, grade) "
                + "SELECT ?, grade FROM grade_retired WHERE sheet_id = ? ORDER BY id", to, from);
        jdbc.update("INSERT INTO void_reason (sheet_id, reason) "
                + "SELECT ?, reason FROM void_reason WHERE sheet_id = ? ORDER BY id", to, from);
        jdbc.update("INSERT INTO claim_template (sheet_id, name, amount, note) "
                + "SELECT ?, name, amount, note FROM claim_template WHERE sheet_id = ? ORDER BY id", to, from);
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date, open_cap) "
                + "SELECT ?, name, from_date, to_date, open_cap FROM period WHERE sheet_id = ? ORDER BY id", to, from);

        // people, in list order
        List<Person> theirs = people.list(from);
        Map<Long, Long> personIds = new HashMap<>();
        Map<Long, Integer> place = new HashMap<>();
        for (Person person : theirs) {
            place.put(person.getId(), place.size());
            personIds.put(person.getId(), copyPerson(person, to));
# POST /api/sheets/{sheetId}/settings — change a setting (body: {key, value, from, user}). The keys are
# clerk-limit: a number of 0.00 or more with up to two decimals, or blank for no limit; and floor: the
# least a claim's live due may be, 0.00 or more with up to two decimals, blank for its default 1.00; and
# terms: the whole days (0 or more) after its date a claim is due by, blank for its default 14; and
# terms-A, terms-B, terms-C: a grade's own terms, which a claim of a person of that grade (on the claim's
# date) takes instead, blank to use the sheet's terms (a claim's due-by is fixed when it is added); and
# late-pct: the percent of an overdue claim's figure charged per full 30 days overdue, 0.00 or more with
# up to two decimals, blank for its default 0.00; and cap: the most a person's due-total may be, 0.00 or
# more with up to two decimals, or blank for none; note-threshold: the due above which a claim needs a
# note before it is opened, 0.00 or more with up to two decimals, or blank for none; and proof-threshold: the due above which a claim needs a
# proof before it is settled or approved, 0.00 or more with up to two decimals, or blank for none; and
# proof-threshold-A, proof-threshold-B, proof-threshold-C: a grade's own proof threshold, which a claim of a
# person of that grade (on the claim's date) takes instead, blank for none (then the sheet's).
# Each of these is dated: its value is recorded from the from-date (yyyy-MM-dd, blank for the sheet's
# today), keeping the values recorded from other dates and replacing one recorded from the same date. A
# claim's floor, late percent, terms and proof threshold are those in force on its date; the clerk limit and cap those in
# force on the sheet's today. policy-date, period-numbering-from and entry-date are not dated (from is ignored);
# entry-date (yyyy-MM-dd, blank for off) is the default date of a new claim in place of the sheet's today.
# parent (not dated): a sheet id, blank for none, whose rates a grade with no rate in force on a date takes, then
# its parent's, up to three levels up; refused when it is this sheet, has this sheet as an ancestor, or was never loaded.
# default-grade (not dated): A, B or C, blank for A; the grade the quick add and an import line with a blank grade give a new person.
# fiscal-start-month (not dated): the month a fiscal year starts in, a whole number from 1 to 12 (1 unless set).
# Any other key or value is refused (400) and nothing is stored. A stored change is recorded in the
# audit file as SETTING_CHANGED, ending from=<date> when a from-date was given (even when the value is the one already in force), then ROLLUP/TOTALS
# for the figures it moved; a refused one records nothing.
validate:
  class: net.officefloor.hq.app.setting.ValidateSetting
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.setting.SaveSetting
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.setting.AuditSettingChanged
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.setting.RespondWithSettings
  govern: [ transaction ]
# GET /api/sheets/{sheetId}/settings — the sheet's settings in force on its today: clerk-limit (two
# decimals, null for no limit) and floor (two decimals, 1.00 until set), and so on; and the floor and
# late percent recorded by from-date (floorFrom, latePctFrom).
respond:
  class: net.officefloor.hq.app.setting.RespondWithSettings
  govern: [ readonly-transaction ]
